void setHasImage()
{
    this.HasImage = this.Image ? true : false;
}

    /// <summary>
    /// Finds the <c>METCompanyImage</c> record
    /// </summary>
    /// <param name = "_refDataareaId">Company for which <c>METCompanyImage</c> record to be found.</param>
    /// <param name = "_refTableId">Tableid which <c>METCompanyImage</c> record to be found.</param>
    /// <param name = "_refRecId">RecId which <c>METCompanyImage</c> record to be found.</param>
    /// <param name = "_forUpdate">A Boolean value that indicates whether to read the record for an update; optional.</param>
    /// <param name = "_imageType">METCompanyImageType</param>
    /// <returns>A record in the <c>METCompanyImage</c> table; otherwise, an empty record.</returns>
    public static METCompanyImage find(
        dataAreaId  _refDataareaId,
        tableId     _refTableId,
        recId       _refRecId,
        boolean     _forUpdate  = false,
        METCompanyImageType _imageType = METCompanyImageType::CompanyLogo)
    {
        METCompanyImage    companyImage;

        if (! _refTableId || ! _refRecId)
        {
            return companyImage;
        }

        companyImage.selectForUpdate(_forUpdate);
        if (_forUpdate)
        {
            select firstonly forupdate companyImage
                index hint RefIdx
                where companyImage.RefCompanyId  == _refDataareaId  &&
                      companyImage.RefTableId    == _refTableId     &&
                      companyImage.RefRecId      == _refRecId &&
                      companyImage.ImageType     == _imageType;
        }
        else
        {
            select firstonly companyImage
            index hint RefIdx
            where companyImage.RefCompanyId  == _refDataareaId  &&
                    companyImage.RefTableId    == _refTableId     &&
                    companyImage.RefRecId      == _refRecId &&
                    companyImage.ImageType     == _imageType;
        }

        return companyImage;
    }

/// <summary>
/// Finds a record in the <c>METCompanyImage</c> table that is related to a specified record.
/// </summary>
/// <param name="_record">
/// The record for which to find the related <c>CompanyImage</c> record.
/// </param>
/// <param name="_forUpdate">
/// A Boolean value that indicates whether to read the record for an update; optional.
/// </param>
/// <param name = "_imageType">METCompanyImageType</param>
/// <returns>
/// A record in the <c>CompanyImage</c> table; otherwise, an empty record.
/// </returns>
public static METCompanyImage findByRecord(Common  _record, boolean _forUpdate  = false, METCompanyImageType _imageType = METCompanyImageType::CompanyLogo)
{
    return METCompanyImage::find(_record.DataAreaId,_record.TableId,_record.RecId,_forUpdate, _imageType);
}
